 public static async Task Run(MainWindow main,PlannerViewModel vm,ScheduleBoard board,string directory,Action<bool,string> check)
 {
  string state=JsonSerializer.Serialize(vm.State,JsonKit.Options);main.SetLayoutMode("AUTO");main.Height=800;main.Width=1000;await Task.Delay(100);check(main.IsCompact&&board.ViewMode=="AGENDA","缩窄窗口自动进入简洁日程");main.Width=1140;await Task.Delay(60);check(main.IsCompact,"自动切换在临界区保留简洁状态");main.Width=1300;await Task.Delay(80);check(!main.IsCompact,"扩大窗口恢复完整模式");main.Width=1140;await Task.Delay(60);check(!main.IsCompact,"自动切换在临界区保留完整状态");
  main.SetLayoutMode("COMPACT");main.Width=400;main.Height=780;await Task.Delay(100);check(main.IsCompact&&Walk(board).OfType<Border>().Count(b=>b.Tag is DateOnly)==7,"简洁模式展示当天和随后六天");check(!Walk(main).OfType<TextBlock>().Any(t=>t.Text=="智能行程助手"&&t.IsVisible),"简洁模式隐藏助手与两侧栏");Capture(main,Path.Combine(directory,"soft-compact.png"));
  var card=Walk(board).OfType<SwipeActivityCard>().First();string key=card.Entry.Occurrence.Key;bool original=vm.Appearance.Completed.Contains(key),favorite=vm.Appearance.Important.Contains(key);Swipe(card,100,0);check(vm.Appearance.Important.Contains(key)!=favorite&&vm.Appearance.Completed.Contains(key)==original,"右滑收藏与完成独立");check(card.Star.Visibility==(card.IsImportant?Visibility.Visible:Visibility.Collapsed),"仅收藏时展示星标");Swipe(card,100,0);check(vm.Appearance.Important.Contains(key)==favorite,"再次右滑取消收藏");
  Swipe(card,-100,0);await Task.Delay(260);check(vm.Appearance.Completed.Contains(key)!=original&&Math.Abs(card.Opacity-(card.IsCompleted?.55:1))<.03,"左滑完成并淡出动画");Swipe(card,-100,0);await Task.Delay(260);check(vm.Appearance.Completed.Contains(key)==original,"再次左滑恢复原状态");Swipe(card,10,0);Swipe(card,3,100);card.BeginSwipe(new(0,0));card.ContinueSwipe(new(100,0));card.EndSwipe(true);check(vm.Appearance.Completed.Contains(key)==original,"短滑竖滑和取消不改变状态");
  card.ContextMenu!.PlacementTarget=card;card.ContextMenu.IsOpen=true;await Task.Delay(50);var action=card.ContextMenu.Items.OfType<MenuItem>().First(i=>Equals(i.Header,original?"恢复未完成":"标记完成"));card.ContextMenu.IsOpen=false;action.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));check(vm.Appearance.Completed.Contains(key)!=original,"右键完成操作保留");Swipe(card,-100,0);await Task.Delay(240);
  double size=Walk(card).OfType<TextBlock>().First(t=>t.Text==card.Entry.Occurrence.Title).FontSize;vm.UpdateAppearance(p=>p.FontSize=18);await Task.Delay(70);var larger=Walk(board).OfType<SwipeActivityCard>().First(c=>c.Entry.Occurrence.Key==key);check(Walk(larger).OfType<TextBlock>().First(t=>t.Text==larger.Entry.Occurrence.Title).FontSize>size,"字号设置实际放大卡片文字");
  main.OpenSettingsCategory("appearance");await Task.Delay(70);var settings=Application.Current.Windows.OfType<SettingsWindow>().Single();Walk(settings).OfType<Slider>().Single().Value=22;await Task.Delay(80);check(vm.Appearance.FontSize==22&&new BoardPreferenceStore(vm.DataDirectory).Load().FontSize==22,"设置字号滑块实时生效并持久化");Capture(settings,Path.Combine(directory,"settings-appearance.png"));
  var search=Walk(settings).OfType<TextBox>().Single(t=>Equals(t.Tag,"SettingsSearch"));search.Text="字号";check(Walk(settings).OfType<Slider>().Single().IsVisible&&!Walk(settings).OfType<PasswordBox>().Any(p=>p.IsVisible),"设置搜索定位字号且隐藏不相关内容");settings.SelectCategory("profile");var nick=Walk(settings).OfType<TextBox>().Single(t=>Equals(t.Tag,"SettingsNickname"));nick.Text="我的旅行";ButtonOf(settings,"保存个人资料").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(vm.Appearance.Nickname=="我的旅行","本地昵称保存并刷新导航");settings.SelectCategory("appearance");var pin=Walk(settings).OfType<CheckBox>().Single(t=>Equals(t.Tag,"SettingsPin"));pin.IsChecked=true;pin.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(main.Topmost,"简洁模式可通过设置置顶");main.Width=320;await Task.Delay(100);check(main.IsCompact&&board.ActualWidth>=280,"大字号下320宽简洁界面可用");Capture(main,Path.Combine(directory,"soft-compact-large-font.png"));settings.Close();vm.UpdateAppearance(p=>p.FontSize=14);
  var empty=Walk(board).OfType<Button>().First(b=>Equals(b.Content,"暂无安排 · 点击添加"));empty.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(40);var editor=Application.Current.Windows.OfType<EditorWindow>().Single();Walk(editor).OfType<TextBox>().First(t=>Equals(t.Tag,"ActivityTitle")).Text="模式切换时保留";main.SetLayoutMode("FULL");await Task.Delay(90);check(!main.IsCompact&&editor.IsVisible&&Walk(editor).OfType<TextBox>().Any(t=>t.Text=="模式切换时保留"),"切回完整模式保留打开的编辑器内容");check(!main.Topmost,"完整模式不保持侧栏置顶");editor.Close();
