  vm.UpdateAppearance(p=>p.FontSize=22);await Task.Delay(70);bool measured=false,reachable=false;var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(40)};timer.Tick+=(_,_)=>{var dialog=Application.Current.Windows.OfType<Window>().FirstOrDefault(w=>w.Title=="行程表设置");if(dialog is null)return;timer.Stop();var scrolling=Walk(dialog).OfType<ScrollViewer>().First();scrolling.ScrollToEnd();dialog.UpdateLayout();var delete=ButtonOf(dialog,"删除行程表");var point=delete.TransformToAncestor(dialog).Transform(new Point(0,delete.ActualHeight));var client=(FrameworkElement)VisualTreeHelper.GetChild(dialog,0);reachable=point.Y<=client.ActualHeight+2&&point.Y>0;measured=true;Capture(dialog,Path.Combine(directory,"table-large.png"));dialog.Close();};timer.Start();Walk(main).OfType<Button>().First(b=>b.Tag is string t&&t.StartsWith("TableEdit:")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));timer.Stop();check(measured&&reachable,"22号字体行程表设置底部操作滚动可达");vm.UpdateAppearance(p=>p.FontSize=14);
  var restoreVm=new PlannerViewModel(Path.Combine(directory,"restore-full"),false);restoreVm.UpdateAppearance(p=>{p.LayoutMode="FULL";p.FullWidth=1260;p.FullHeight=760;});var restored=new MainWindow(restoreVm);restored.Show();await Task.Delay(90);bool restoredSize=Math.Abs(restored.Width-1260)<2&&Math.Abs(restored.Height-760)<2;restored.Close();check(restoredSize,"完整模式重启恢复已保存窗口尺寸");
  vm.UpdateAppearance(p=>{p.TablesPanelOpen=false;p.AssistantPanelOpen=false;p.SidebarExpanded=false;});main.Width=1480;main.Height=920;board.SetView("MONTH");board.NavigateTo(Clock.Today);await Task.Delay(90);Capture(main,Path.Combine(directory,"soft-full-month.png"));board.SetView("LIST");await Task.Delay(70);Capture(main,Path.Combine(directory,"soft-full-list.png"));board.SetView("MONTH");
 }
 static void Swipe(SwipeActivityCard c,double x,double y){c.BeginSwipe(new(0,0));c.ContinueSwipe(new(x,y));c.EndSwipe();}
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;foreach(var c in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var d in Walk(c))yield return d;}
 static Button ButtonOf(DependencyObject root,string name)=>Walk(root).OfType<Button>().First(b=>Equals(b.Content,name));
 static Button TagButton(DependencyObject root,string tag)=>Walk(root).OfType<Button>().First(b=>Equals(b.Tag,tag));
 static void Capture(Window window,string path){window.UpdateLayout();var e=(FrameworkElement)window.Content;int w=(int)Math.Ceiling(e.ActualWidth),h=(int)Math.Ceiling(e.ActualHeight);var image=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var dc=bg.RenderOpen())dc.DrawRectangle(window.Background,null,new Rect(0,0,w,h));image.Render(bg);image.Render(e);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using var file=File.Create(path);png.Save(file);}
}
